import React from 'react';
import { GamesShowcaseProps } from './GamesShowcase.types';
import { useI18n } from '../../hooks/useI18n';
import catervaImage from '../../assets/CATERVA_OD.jpg';
import sanMartinESImage from '../../assets/SanMartin_ES.webp';
import sanMartinENGImage from '../../assets/SanMartin_ENG.webp';
import {
  GamesShowcaseContainer,
  GamesGrid,
  GameItem,
  GameImage,
  GameTitle
} from './GamesShowcase.styles';

const GamesShowcase: React.FC<GamesShowcaseProps> = ({ className, style }) => {
  const { t, language } = useI18n();

  const handleCatervaClick = () => {
    window.open('https://s.team/a/5012060', '_blank');
  };

  const handleSanMartinClick = () => {
    window.open('https://s.team/a/5023240', '_blank');
  };

  const getSanMartinImage = () => {
    return language === 'es' ? sanMartinESImage : sanMartinENGImage;
  };

  return (
    <GamesShowcaseContainer className={className} style={style}>
      <GamesGrid>
        <GameItem onClick={handleCatervaClick} role="button" tabIndex={0}
          onKeyDown={(e: React.KeyboardEvent<HTMLDivElement>) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              handleCatervaClick();
            }
          }}
          aria-label={`${t('games.caterva.title')} - Open Steam store page`}
        >
          <GameImage
            src={catervaImage}
            alt={t('games.caterva.title')}
          />
          <GameTitle>
            {t('games.caterva.title')}
          </GameTitle>
        </GameItem>

        <GameItem onClick={handleSanMartinClick} role="button" tabIndex={0}
          onKeyDown={(e: React.KeyboardEvent<HTMLDivElement>) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              handleSanMartinClick();
            }
          }}
          aria-label={`${t('games.sanMartin.title')} - Open Steam store page`}
        >
          <GameImage
            src={getSanMartinImage()}
            alt={t('games.sanMartin.title')}
          />
          <GameTitle>
            {t('games.sanMartin.title')}
          </GameTitle>
        </GameItem>
      </GamesGrid>
    </GamesShowcaseContainer>
  );
};

export default GamesShowcase;