import React, { useState, useEffect } from 'react';
import './App.css';
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';
import { HomeContent, GamesContent, AboutContent } from './components/sections';
import { useI18n } from './hooks/useI18n';

const App = (): React.JSX.Element => {
  const { t } = useI18n();
  const [allAssetsLoaded, setAllAssetsLoaded] = useState(false);
  const [showMainContent, setShowMainContent] = useState(false);
  const [fadeLoading, setFadeLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<string>('home');

  useEffect(() => {
    setTimeout(() => {
      setAllAssetsLoaded(true);
      setFadeLoading(true);
      setTimeout(() => {
        setShowMainContent(true);
      }, 500);
    }, 1000);
  }, []);

  const handleNavigationChange = (tabKey: string): void => {
    setActiveTab(tabKey);
  };

  const renderActiveContent = (): React.JSX.Element => {
    switch (activeTab) {
      case 'games':
        return <GamesContent />;
      case 'about':
        return <AboutContent />;
      case 'home':
      default:
        return <HomeContent />;
    }
  };

  return (
    <div className="app-container">
      {!showMainContent && (
        <div className={`loading-screen ${fadeLoading ? 'fade-out' : ''}`}>
          <div className="loading-text">{t('loading')}</div>
        </div>
      )}

      {allAssetsLoaded && (
        <div className={`App ${showMainContent ? 'fade-in' : 'hidden'}`}>
          <Header
            activeItemKey={activeTab}
            onNavigationChange={handleNavigationChange}
          />
          <main className="main-content" id="main-content" tabIndex={-1}>
            <section className="content-section">
              {renderActiveContent()}
            </section>
          </main>
          <Footer />
        </div>
      )}
    </div>
  );
};

export default App;
