import React from 'react';
import { useI18n } from '../../hooks/useI18n';
import { HeroTaglineContainer, HeroTaglineText, FirstPart, Comma, SecondPart } from './HeroTagline.styles';
import { HeroTaglineProps } from './HeroTagline.types';

const HeroTagline: React.FC<HeroTaglineProps> = ({ className }) => {
  const { t } = useI18n();
  
  const tagline = t('hero.tagline');
  const isSpanish = tagline.includes('DISTORSIONA');
  
  if (isSpanish) {
    return (
      <HeroTaglineContainer className={className}>
        <HeroTaglineText>
          <FirstPart>DONDE LA REALIDAD SE DISTORSIONA</FirstPart>
          <Comma>,</Comma>
          <SecondPart> EL JUEGO COMIENZA</SecondPart>
        </HeroTaglineText>
      </HeroTaglineContainer>
    );
  }
  
  return (
    <HeroTaglineContainer className={className}>
      <HeroTaglineText>
        <FirstPart>WHERE REALITY DISTORTS</FirstPart>
        <Comma>,</Comma>
        <SecondPart> THE GAME BEGINS</SecondPart>
      </HeroTaglineText>
    </HeroTaglineContainer>
  );
};

export default HeroTagline;
